        Question(11714, "En quelle année \"Bad\" de Michael Jackson a-t-il remporté un Grammy?", listOf("1988", "1986", "1990", "1987"), 0, "Culture", Difficulty.HARD, explanation = "Bad de Michael Jackson a remporté un Grammy en 1988 dans la catégorie Meilleure performance vocale pop masculine pour la chanson titre."),
        Question(11715, "Quel est le plus grand nombre de Grammy Awards remportés par un artiste en une nuit?", listOf("8", "6", "10", "5"), 0, "Culture", Difficulty.HARD, explanation = "Michael Jackson a remporté 8 Grammy Awards en une seule nuit en 1984, un record toujours inégalé."),
        Question(11716, "Qui a remporté le Grammy Award du Meilleur Album en 2023?", listOf("Harry Styles", "Beyoncé", "Taylor Swift", "Miley Cyrus"), 1, "Culture", Difficulty.HARD, explanation = "Beyoncé a remporté le Grammy Award du Meilleur Album en 2023 pour son album \"Renaissance\", un hommage à la culture ballroom et dance. C'était la première fois qu'elle gagnait cette catégorie après plusieurs nominations."),
        Question(11717, "Quel artiste français a remporté le plus de Grammys?", listOf("David Guetta", "Justice", "Daft Punk", "Stéphane Grappelli"), 3, "Culture", Difficulty.HARD, explanation = "Stéphane Grappelli, célèbre violoniste de jazz, a remporté un Grammy Award en 1997 pour l'ensemble de sa carrière, ce qui constitue le record pour un artiste français."),
        Question(11718, "En quelle année Daft Punk a-t-il remporté un Grammy?", listOf("2002", "2000", "2004", "2001"), 0, "Culture", Difficulty.HARD, explanation = "Daft Punk a remporté son premier Grammy en 2002 pour l'album *Discovery*, dans la catégorie du meilleur album de musique électronique/dance."),
        Question(11719, "Combien de Grammys The Beatles ont-ils remportés?", listOf("7", "5", "10", "3"), 1, "Culture", Difficulty.HARD, explanation = "The Beatles ont remporté 7 Grammy Awards, mais ce chiffre inclut des récompenses individuelles et collectives. Le groupe en tant que tel en a obtenu 5, notamment pour l'Album de l'année avec Sgt. Pepper's Lonely Hearts Club Band."),
        Question(11720, "Quel artiste a remporté le Grammy du meilleur nouvel artiste en 2024?", listOf("Victoria Monét", "Olivia Rodrigo", "The Kid LAROI", "Billie Eilish"), 0, "Culture", Difficulty.HARD, explanation = "Victoria Monét a remporté le Grammy du meilleur nouvel artiste en 2024, après une carrière d'auteure-compositrice pour d'autres artistes, notamment Ariana Grande."),
        Question(11721, "En quelle année Aretha Franklin a-t-elle remporté son premier Grammy?", listOf("1967", "1965", "1969", "1963"), 0, "Culture", Difficulty.HARD, explanation = "Aretha Franklin a remporté son premier Grammy en 1967 pour la chanson \"Respect\", qui est devenue un hymne emblématique."),
        Question(11722, "Combien de Grammys Aretha Franklin a-t-elle remportés?", listOf("18", "15", "20", "12"), 0, "Culture", Difficulty.HARD, explanation = "Aretha Franklin a remporté 18 Grammy Awards au cours de sa carrière, dont 11 dans la catégorie de la meilleure performance vocale R&B féminine. Elle détient le record du plus grand nombre de Grammy remportés par une artiste féminine."),
        Question(11723, "Quel est le seul album ayant remporté les quatre Grammy les plus importants?", listOf("Thriller", "Abbey Road", "Sgt. Pepper's", "The Dark Side of the Moon"), 0, "Culture", Difficulty.EXPERT, explanation = "L'album Thriller de Michael Jackson a remporté en 1984 les quatre Grammy majeurs : album de l'année, disque de l'année, chanson de l'année et meilleure performance pop masculine. Aucun autre album n'a réussi cet exploit depuis."),
        Question(11724, "En quelle année Kanye West a-t-il remporté son premier Grammy?", listOf("2004", "2002", "2006", "2005"), 0, "Culture", Difficulty.HARD, explanation = "Kanye West a remporté son premier Grammy en 2004 pour son album \"The College Dropout\", qui a été nominé dans plusieurs catégories et a remporté le prix du meilleur album rap."),
        Question(11725, "Combien de Grammys Kanye West a-t-il remportés?", listOf("24", "20", "30", "15"), 0, "Culture", Difficulty.HARD, explanation = "Kanye West a remporté 24 Grammy Awards, ce qui fait de lui l'un des artistes les plus récompensés de l'histoire de la cérémonie, notamment pour ses albums et productions innovantes."),
        Question(11726, "Quel est le Grammy Award pour la meilleure performance vocale féminine?", listOf("Best Pop Vocal Album", "Best Solo Pop Vocal Album", "Best Female Pop Vocal Album", "Best Pop Female Vocal"), 1, "Culture", Difficulty.HARD, explanation = "Le Grammy Award pour la meilleure performance vocale féminine a été renommé en 2012 pour devenir le Best Pop Solo Performance, puis intégré au Best Pop Solo Vocal Album."),
        Question(11727, "En quelle année Taylor Swift a-t-elle remporté son premier Grammy?", listOf("2010", "2008", "2012", "2009"), 0, "Culture", Difficulty.HARD, explanation = "Taylor Swift a remporté son premier Grammy en 2010 pour son album *Fearless*, qui a été nommé Album de l'année."),
        Question(11728, "Combien de Grammys Taylor Swift a-t-elle remportés?", listOf("12", "10", "15", "8"), 0, "Culture", Difficulty.HARD, explanation = "Taylor Swift a remporté 12 Grammy Awards sur 52 nominations, ce qui en fait l'une des artistes les plus récompensées de l'histoire de la cérémonie."),
        Question(11729, "Quel artiste a remporté le Grammy du meilleur album rap en 2024?", listOf("Killer Mike", "Metro Boomin", "J. Cole", "Drake"), 0, "Culture", Difficulty.HARD, explanation = "Killer Mike a remporté le Grammy du meilleur album rap en 2024 pour son album \"Michael\", qui rend hommage à son héritage et à ses racines musicales."),
        Question(11730, "En quelle année Céline Dion a-t-elle remporté son premier Grammy?", listOf("1991", "1989", "1993", "1990"), 0, "Culture", Difficulty.HARD, explanation = "Céline Dion a remporté son premier Grammy en 1991 dans la catégorie de la meilleure prestation pop par un duo ou un groupe pour la chanson \"When the Night Is Cold\" avec Peabo Bryson."),
        // MUSIQUE - GENRES (551-600)
        Question(11731, "Quel est l'instrument principal du jazz?", listOf("Saxophone", "Piano", "Trompette", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le jazz se caractérise par une grande diversité instrumentale, où le saxophone, la trompette, le piano et la contrebasse sont tous essentiels selon les styles et les époques."),
        Question(11732, "En quelle année le rock 'n' roll a-t-il émergé?", listOf("1954", "1952", "1956", "1950"), 0, "Culture", Difficulty.HARD, explanation = "1954 est souvent citée car c'est l'année du premier enregistrement studio de \"That's All Right\" par Elvis Presley, marquant un tournant médiatique pour le genre."),
        Question(11733, "Qui est le roi du rock and roll?", listOf("Elvis Presley", "Chuck Berry", "Little Richard", "Jerry Lee Lewis"), 0, "Culture", Difficulty.EASY, explanation = "Elvis Presley a popularisé le rock and roll dans les années 1950 avec des tubes comme \"Heartbreak Hotel\" et \"Jailhouse Rock\", devenant une icône culturelle mondiale."),
        Question(11734, "Quel genre musical est issu de la Nouvelle-Orléans?", listOf("Jazz", "Blues", "Rock and roll", "Country"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le jazz est né à la Nouvelle-Orléans au début du XXe siècle, mêlant blues, ragtime et musiques afro-américaines."),
        Question(11735, "Quel est le pays d'origine de la musique reggae?", listOf("Jamaïque", "Haïti", "Trinité-et-Tobago", "Bahamas"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le reggae est né en Jamaïque dans les années 1960, issu du ska et du rocksteady, popularisé mondialement par des artistes comme Bob Marley."),
        Question(11736, "Quel artiste est connu comme le roi du reggae?", listOf("Bob Marley", "Peter Tosh", "Burning Spear", "Gregory Isaacs"), 0, "Culture", Difficulty.EASY, explanation = "Bob Marley a popularisé le reggae à l'international dans les années 1970 avec des titres comme \"No Woman, No Cry\" et \"One Love\", devenant l'icône mondiale du genre."),
        Question(11737, "Quel genre musical a émergé en Afrique du Sud?", listOf("Kwaito", "Mbaqanga", "Gumboot music", "Tous les précédents"), 3, "Culture", Difficulty.HARD, explanation = "L'Afrique du Sud a vu émerger de nombreux genres musicaux influents comme le jazz, le kwaito, le mbaqanga et le gqom, chacun reflétant une époque et une culture spécifiques."),
        Question(11738, "Quel est le pays d'origine de la musique électronique?", listOf("Allemagne", "France", "États-Unis", "Royaume-Uni"), 0, "Culture", Difficulty.HARD, explanation = "L'Allemagne est considérée comme le berceau de la musique électronique moderne, notamment grâce à l'influence du groupe Kraftwerk dans les années 1970, pionnier de l'utilisation des synthétiseurs."),
        Question(11739, "Quel groupe a révolutionné la musique électronique en Europe?", listOf("Kraftwerk", "Tangerine Dream", "Jean-Michel Jarre", "Vangelis"), 0, "Culture", Difficulty.HARD, explanation = "Kraftwerk, groupe allemand formé en 1970, est considéré comme le pionnier de la musique électronique moderne avec des albums comme Autobahn et The Man-Machine."),
        Question(11740, "Quel genre musical est issu du Brésil?", listOf("Bossa Nova", "Samba", "Forró", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le Brésil est le berceau de nombreux genres musicaux reconnus mondialement, comme la samba, la bossa nova, le forró et le funk carioca, ce qui rend la réponse \"tous les précédents\" correcte."),
        Question(11741, "Quel est le pays d'origine du flamenco?", listOf("Espagne", "Andalousie", "Catalogne", "Grenade"), 0, "Culture", Difficulty.EASY, explanation = "Le flamenco est né en Andalousie, au sud de l'Espagne, issu du mélange des cultures gitane, arabe et andalouse."),
        Question(11742, "Quel est le pays d'origine de la musique classique?", listOf("Autriche", "Italie", "Allemagne", "France"), 0, "Culture", Difficulty.MEDIUM, explanation = "L'Autriche est considérée comme un berceau de la musique classique grâce à des compositeurs majeurs comme Mozart, Haydn et Schubert, qui y ont vécu et travaillé. Vienne était un centre culturel incontournable pour ce genre musical."),
        Question(11743, "Quel est le pays d'origine de la musique country?", listOf("États-Unis", "Australie", "Canada", "Nouvelle-Zélande"), 0, "Culture", Difficulty.EASY, explanation = "La musique country est née dans le sud des États-Unis au début du XXe siècle, mêlant influences folk, blues et gospel."),
        Question(11744, "Quel genre musical a émergé à Detroit?", listOf("Motown", "Garage rock", "Techno", "House"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le label Motown, fondé à Detroit en 1959 par Berry Gordy, a popularisé un style de soul et de pop aux influences rhythm and blues."),
        Question(11745, "Quel genre musical a émergé à Chicago?", listOf("Chicago blues", "House music", "Funk", "Gospel"), 0, "Culture", Difficulty.HARD, explanation = "Le Chicago blues est un style de blues électrique qui s'est développé à Chicago dans les années 1940 et 1950, notamment grâce à l'arrivée de musiciens afro-américains venus du Sud des États-Unis."),
        Question(11746, "Quel est le pays d'origine de la musique punk?", listOf("Royaume-Uni", "États-Unis", "France", "Allemagne"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le punk rock est né au Royaume-Uni et aux États-Unis au milieu des années 1970, mais le mouvement punk britannique, avec des groupes comme les Sex Pistols, a popularisé le genre à l'échelle mondiale."),
        Question(11747, "Quel groupe britannique a révolutionné le punk?", listOf("The Sex Pistols", "The Clash", "The Ramones", "New York Dolls"), 0, "Culture", Difficulty.MEDIUM, explanation = "The Sex Pistols ont popularisé le punk rock avec leur album Never Mind the Bollocks et leur attitude provocatrice, marquant une rupture radicale avec le rock des années 1970."),
        Question(11748, "Quel est le pays d'origine de la musique reggaeton?", listOf("Porto Rico", "Jamaïque", "République Dominicaine", "Trinité-et-Tobago"), 0, "Culture", Difficulty.HARD, explanation = "Le reggaeton est né à Porto Rico dans les années 1990, fusionnant le reggae jamaïcain, le dancehall et le hip-hop latino-américain."),
        Question(11749, "Quel genre musical est populaire en Afrique de l'Ouest?", listOf("Afrobeat", "Highlife", "Juju", "Tous les précédents"), 3, "Culture", Difficulty.HARD, explanation = "L'Afrique de l'Ouest est un foyer de diversité musicale où des genres comme l'afrobeat, le highlife, le mbalax et le coupé-décalé sont populaires, chacun ayant des racines et des styles distincts."),
        Question(11750, "Quel artiste nigérian a popularisé l'afrobeat?", listOf("Fela Kuti", "King Sunny Ade", "Wizkid", "Burna Boy"), 0, "Culture", Difficulty.MEDIUM, explanation = "Fela Kuti a créé et popularisé l'afrobeat dans les années 1970 en fusionnant le highlife, le funk et le jazz avec des paroles politiquement engagées."),
        // MUSIQUE - INSTRUMENTS (601-650)
        Question(11751, "Quel est l'instrument le plus ancien?", listOf("Flûte", "Tambour", "Lyre", "Harpe"), 0, "Culture", Difficulty.HARD, explanation = "Des flûtes en os et en ivoire datant de plus de 40 000 ans ont été découvertes dans le Jura souabe, en Allemagne, ce qui en fait les plus anciens instruments de musique connus."),
        Question(11752, "Combien de cordes a une guitare classique?", listOf("6", "7", "8", "5"), 0, "Culture", Difficulty.EASY, explanation = "La guitare classique, comme la plupart des guitares acoustiques et électriques standard, possède traditionnellement six cordes, accordées en mi, la, ré, sol, si, mi."),
        Question(11753, "Quel instrument a le son le plus grave?", listOf("Contrebasse", "Tuba", "Violoncelle", "Basson"), 0, "Culture", Difficulty.MEDIUM, explanation = "La contrebasse est l'instrument à cordes frottées le plus grand et le plus grave de l'orchestre, produisant des fréquences très basses."),
        Question(11754, "Quel instrument est typiquement utilisé en jazz?", listOf("Saxophone", "Trompette", "Piano", "Tous les précédents"), 3, "Culture", Difficulty.EASY, explanation = "Le jazz utilise une grande variété d'instruments, incluant le saxophone, la trompette, le piano et la contrebasse, donc aucun choix unique n'est exclusif."),
        Question(11755, "Combien de touches a un piano?", listOf("88", "85", "90", "100"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le piano standard moderne possède 88 touches, soit 52 blanches et 36 noires, couvrant sept octaves et une tierce mineure."),
        Question(11756, "Quel instrument est traditionnel en Inde?", listOf("Sitar", "Tabla", "Sarod", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le sitar, le tabla et la veena sont tous des instruments traditionnels indiens, chacun jouant un rôle majeur dans la musique classique du pays."),
        Question(11757, "Quel instrument est traditionnel au Japon?", listOf("Shamisen", "Koto", "Shakuhachi", "Tous les précédents"), 3, "Culture", Difficulty.HARD, explanation = "Le Japon possède plusieurs instruments traditionnels emblématiques comme le shamisen, le koto et la flûte shakuhachi, donc toutes les réponses proposées étaient valables."),
        Question(11758, "Quel instrument est traditionnel en Indonésie?", listOf("Gamelan", "Angklung", "Gong", "Tous les précédents"), 3, "Culture", Difficulty.HARD, explanation = "L'Indonésie possède une grande diversité d'instruments traditionnels comme le gamelan, l'angklung ou le sasando, chacun représentant une région ou une culture spécifique."),
        Question(11759, "Quel instrument à vent est le plus grave?", listOf("Tuba", "Basson", "Cor anglais", "Clarinette basse"), 0, "Culture", Difficulty.HARD, explanation = "Le tuba est l'instrument à vent le plus grave de l'orchestre symphonique, produisant les notes les plus basses grâce à sa grande taille et son pavillon large."),
        Question(11760, "Quel instrument à vent est le plus aigu?", listOf("Piccolo", "Flûte", "Clarinette", "Hautbois"), 0, "Culture", Difficulty.HARD, explanation = "Le piccolo est une flûte traversière de petite taille, dont la tessiture est environ une octave plus haute que celle de la flûte standard, ce qui en fait l'instrument à vent le plus aigu de l'orchestre."),
        Question(11761, "Combien de cordes a un violon?", listOf("4", "5", "3", "6"), 0, "Culture", Difficulty.EASY, explanation = "Le violon a quatre cordes, accordées en sol, ré, la et mi, une configuration standard depuis le XVIe siècle."),
        Question(11762, "Quel instrument est typiquement utilisé en musique classique?", listOf("Violon", "Violoncelle", "Alto", "Tous les précédents"), 3, "Culture", Difficulty.EASY, explanation = "La musique classique utilise une grande variété d'instruments, incluant cordes, bois, cuivres et percussions, donc tous les instruments cités sont typiques."),
        Question(11763, "Quel instrument produisit le style musical \"slide guitar\"?", listOf("Guitare slide", "Guitare acoustique", "Guitare électrique", "Harmonica"), 0, "Culture", Difficulty.HARD, explanation = "La slide guitar se joue en faisant glisser un objet (bouteille, métal) sur les cordes, ce qui produit un son continu et glissé typique du blues."),
        Question(11764, "Quel instrument est traditionnellement utilisé pour produire le son du blues?", listOf("Harmonica", "Guitare acoustique", "Guitare électrique", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le blues utilise une variété d'instruments comme la guitare, l'harmonica et le piano, chacun apportant une texture sonore caractéristique au genre."),
        Question(11765, "Quel est l'instrument à percussion le plus ancien?", listOf("Tambour", "Cymbale", "Gong", "Xylophone"), 0, "Culture", Difficulty.HARD, explanation = "Des tambours primitifs en peau tendue sur un tronc d'arbre ou une carapace de tortue datent de la Préhistoire, utilisés pour la communication et les rituels."),
        Question(11766, "Quel instrument est typique de l'orchestre d'harmonie?", listOf("Trompette", "Trombone", "Tuba", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "Un orchestre d'harmonie regroupe des instruments à vent (bois et cuivres) et des percussions, mais pas de cordes frottées. La bonne réponse inclut donc tous les instruments typiques de cette formation."),
        Question(11767, "Quel instrument produit le son du mellotron?", listOf("Clavier électrique", "Synthétiseur", "Piano électrique", "Orgue"), 0, "Culture", Difficulty.HARD, explanation = "Le mellotron est un instrument à clavier électrique qui utilise des bandes magnétiques préenregistrées pour reproduire des sons d'orchestre ou de chœur."),
        Question(11768, "Quel instrument est le plus utilisé en musique électronique?", listOf("Synthétiseur", "Clavier", "Séquenceur", "Tous les précédents"), 3, "Culture", Difficulty.MEDIUM, explanation = "La musique électronique repose sur une grande variété d'instruments comme les synthétiseurs, boîtes à rythmes et ordinateurs, aucun n'étant universellement dominant."),
        Question(11769, "Quel instrument a été inventé par Adolphe Sax?", listOf("Saxophone", "Trombone", "Clarinette", "Hautbois"), 0, "Culture", Difficulty.MEDIUM, explanation = "Adolphe Sax, facteur d'instruments belge, a breveté le saxophone en 1846. Il cherchait à créer un instrument à vent à anche simple combinant la puissance des cuivres et la souplesse des bois."),
        Question(11770, "Quel instrument est la base de la musique baroque?", listOf("Clavecin", "Piano", "Clavicorde", "Orgue"), 0, "Culture", Difficulty.HARD, explanation = "Le clavecin était l'instrument roi de la période baroque (XVIIe-XVIIIe siècles), servant de base harmonique et rythmique dans la musique d'ensemble, notamment dans la basse continue."),
        // MUSIQUE - COMPOSITEURS CLASSIQUES (651-700)
        Question(11771, "Quel compositeur a écrit \"Les Quatre Saisons\"?", listOf("Antonio Vivaldi", "Ludwig van Beethoven", "Wolfgang Amadeus Mozart", "Johann Sebastian Bach"), 0, "Culture", Difficulty.EASY, explanation = "Antonio Vivaldi, compositeur baroque italien, a composé ce célèbre cycle de quatre concertos pour violon en 1723, chacun représentant une saison de l'année."),
        Question(11772, "En quelle année \"Les Quatre Saisons\" a-t-il été composé?", listOf("1725", "1720", "1730", "1735"), 0, "Culture", Difficulty.HARD, explanation = "Antonio Vivaldi composa \"Les Quatre Saisons\" en 1723, mais l'œuvre fut publiée en 1725 dans le recueil \"Il cimento dell'armonia e dell'inventione\"."),
        Question(11773, "Quel compositeur a écrit la \"Symphonie n°9\"?", listOf("Ludwig van Beethoven", "Wolfgang Amadeus Mozart", "Joseph Haydn", "Franz Schubert"), 0, "Culture", Difficulty.EASY, explanation = "La Neuvième Symphonie de Beethoven, achevée en 1824, est célèbre pour son finale avec chœur sur l'« Ode à la joie » de Schiller."),
        Question(11774, "Quel compositeur a écrit \"Eine kleine Nachtmusik\"?", listOf("Wolfgang Amadeus Mozart", "Ludwig van Beethoven", "Joseph Haydn", "Franz Schubert"), 0, "Culture", Difficulty.MEDIUM, explanation = "Mozart a composé cette sérénade en 1787 à Vienne. Le titre signifie \"une petite musique de nuit\" en allemand."),
        Question(11775, "Quel compositeur a écrit \"L'Art de la Fugue\"?", listOf("Johann Sebastian Bach", "George Frideric Handel", "Antonio Vivaldi", "Arcangelo Corelli"), 0, "Culture", Difficulty.HARD, explanation = "Johann Sebastian Bach a composé L'Art de la Fugue dans les années 1740, une œuvre inachevée qui explore de manière exhaustive les possibilités de la fugue, un contrepoint complexe."),
        Question(11776, "Quel compositeur a écrit \"Carmina Burana\"?", listOf("Carl Orff", "Gustav Holst", "Edward Elgar", "Ralph Vaughan Williams"), 0, "Culture", Difficulty.HARD, explanation = "Carl Orff a composé Carmina Burana en 1937, une cantate scénique basée sur des poèmes médiévaux découverts dans un manuscrit bavarois."),
        Question(11777, "Quel compositeur a écrit \"La Marche des Toreadors\"?", listOf("Georges Bizet", "Gioachino Rossini", "Giuseppe Verdi", "Giacomo Puccini"), 0, "Culture", Difficulty.HARD, explanation = "Georges Bizet a composé \"La Marche des Toreadors\" pour son opéra \"Carmen\", créé en 1875. Ce morceau célèbre accompagne l'entrée des toreros dans l'arène."),
        Question(11778, "Quel compositeur a écrit \"Clair de Lune\"?", listOf("Claude Debussy", "Maurice Ravel", "Erik Satie", "Gabriel Fauré"), 0, "Culture", Difficulty.MEDIUM, explanation = "Clair de lune est le troisième mouvement de la Suite bergamasque de Claude Debussy, composée en 1890 et publiée en 1905."),
        Question(11779, "Quel compositeur a écrit \"La Mer\"?", listOf("Claude Debussy", "Maurice Ravel", "Erik Satie", "Gabriel Fauré"), 0, "Culture", Difficulty.HARD, explanation = "Claude Debussy a composé \"La Mer\" entre 1903 et 1905, une œuvre orchestrale majeure du mouvement impressionniste en musique."),
        Question(11780, "Quel compositeur a écrit \"Bolero\"?", listOf("Maurice Ravel", "Claude Debussy", "Erik Satie", "Gabriel Fauré"), 0, "Culture", Difficulty.EASY, explanation = "Maurice Ravel a composé le Boléro en 1928 pour un ballet commandé par Ida Rubinstein. C'est l'une de ses œuvres les plus célèbres, connue pour son unique thème répété et crescendo orchestral."),
        Question(11781, "Quel compositeur a écrit \"Gymnopédie\"?", listOf("Erik Satie", "Claude Debussy", "Maurice Ravel", "Gabriel Fauré"), 0, "Culture", Difficulty.HARD, explanation = "Erik Satie a composé les trois Gymnopédies pour piano entre 1888 et 1895, des pièces au style minimaliste et mélancolique qui ont marqué la musique française."),
        Question(11782, "Quel compositeur a écrit \"Casse-Noisette\"?", listOf("Piotr Ilitch Tchaïkovski", "Sergei Prokofiev", "Anatoly Lyadov", "Modest Mussorgski"), 0, "Culture", Difficulty.EASY, explanation = "Tchaïkovski a composé \"Casse-Noisette\" en 1892, un ballet en deux actes basé sur un conte d'Alexandre Dumas. C'est l'une de ses œuvres les plus célèbres, souvent jouée pendant la période de Noël."),
        Question(11783, "Quel compositeur a écrit \"Lac des Cygnes\"?", listOf("Piotr Ilitch Tchaïkovski", "Sergei Prokofiev", "Anatoly Lyadov", "Modest Mussorgski"), 0, "Culture", Difficulty.EASY, explanation = "Tchaïkovski a composé \"Le Lac des Cygnes\" en 1875-1876, sur commande du Théâtre Bolchoï. C'est l'un des ballets les plus célèbres du répertoire classique."),
        Question(11784, "Quel compositeur a écrit \"La Damnation de Faust\"?", listOf("Hector Berlioz", "Georges Bizet", "Gioachino Rossini", "Giuseppe Verdi"), 0, "Culture", Difficulty.HARD, explanation = "Berlioz composa cette \"légende dramatique\" en 1846, inspiré par la traduction de Gérard de Nerval du Faust de Goethe."),
