        Question(11856, "En quelle année Dizzy Gillespie a-t-il enregistré \"A Night in Tunisia\"?", listOf("1946", "1944", "1948", "1945"), 0, "Culture", Difficulty.EXPERT, explanation = "Dizzy Gillespie a enregistré \"A Night in Tunisia\" en 1946, une pièce emblématique du bebop qu'il avait composée quelques années plus tôt."),
        Question(11857, "Quel pianiste est considéré comme le plus grand de l'histoire du jazz?", listOf("Art Tatum", "Duke Ellington", "Oscar Peterson", "Bill Evans"), 0, "Culture", Difficulty.HARD, explanation = "Art Tatum est reconnu pour sa virtuosité technique exceptionnelle et son harmonie complexe, révolutionnant le jazz dans les années 1930-40."),
        Question(11858, "En quelle année \"In a Silent Way\" a-t-il été enregistré?", listOf("1969", "1967", "1971", "1970"), 0, "Culture", Difficulty.HARD, explanation = "\"In a Silent Way\" marque un tournant dans la carrière de Miles Davis vers le jazz fusion, et a été enregistré en février 1969."),
        Question(11859, "Quel compositeur a écrit \"Take Five\"?", listOf("Dave Brubeck", "Bill Evans", "Oscar Peterson", "Thelonious Monk"), 0, "Culture", Difficulty.HARD, explanation = "Dave Brubeck a composé \"Take Five\" en 1959 pour son album \"Time Out\". Ce morceau est célèbre pour son rythme inhabituel en 5/4, une signature temporelle rare dans le jazz."),
        Question(11860, "En quelle année \"Take Five\" a-t-il été enregistré?", listOf("1959", "1957", "1961", "1958"), 0, "Culture", Difficulty.HARD, explanation = "Composé par Paul Desmond et popularisé par le Dave Brubeck Quartet, \"Take Five\" a été enregistré en 1959 pour l'album \"Time Out\"."),
        Question(11861, "Quel est le bassiste le plus influent du jazz?", listOf("Charles Mingus", "Ray Brown", "Paul Chambers", "Oscar Pettiford"), 0, "Culture", Difficulty.HARD, explanation = "Charles Mingus est considéré comme l'un des bassistes et compositeurs les plus novateurs du jazz, mêlant blues, gospel et free jazz dans des œuvres comme \"Mingus Ah Um\"."),
        Question(11862, "En quelle année \"Mingus Ah Um\" a-t-il été enregistré?", listOf("1959", "1957", "1961", "1958"), 0, "Culture", Difficulty.EXPERT, explanation = "\"Mingus Ah Um\" est un album de jazz emblématique de Charles Mingus, enregistré en 1959, une année faste pour le jazz avec des chefs-d’œuvre comme \"Kind of Blue\" de Miles Davis."),
        Question(11863, "Quel compositeur a écrit \"Round Midnight\"?", listOf("Thelonious Monk", "Duke Ellington", "Charlie Parker", "Dizzy Gillespie"), 0, "Culture", Difficulty.HARD, explanation = "Thelonious Monk a composé \"Round Midnight\" dans les années 1940, devenant l'un des standards de jazz les plus enregistrés."),
        Question(11864, "En quelle année \"Blue Train\" a-t-il été enregistré?", listOf("1957", "1955", "1959", "1958"), 0, "Culture", Difficulty.EXPERT, explanation = "Blue Train est un album de John Coltrane, enregistré en 1957 pour le label Blue Note, et il est considéré comme un chef-d'œuvre du jazz hard bop."),
        Question(11865, "Quel vocalist est considéré comme le meilleur du jazz?", listOf("Ella Fitzgerald", "Sarah Vaughan", "Billie Holiday", "Tous les précédents"), 3, "Culture", Difficulty.HARD, explanation = "Le jazz a vu émerger de nombreux vocalistes légendaires comme Ella Fitzgerald, Billie Holiday ou Louis Armstrong, chacun excellent dans un style différent, rendant impossible de désigner un seul meilleur."),
        Question(11866, "En quelle année \"Body and Soul\" a-t-il été enregistré par Coleman Hawkins?", listOf("1939", "1937", "1941", "1940"), 0, "Culture", Difficulty.EXPERT, explanation = "Coleman Hawkins a enregistré \"Body and Soul\" le 11 octobre 1939 lors d'une session pour le label Bluebird, et cette version est devenue un standard du jazz."),
        Question(11867, "Quel compositeur a écrit \"Autumn Leaves\"?", listOf("Joseph Kosma", "Jacques Prévert", "Yip Harburg", "Tous les précédents"), 3, "Culture", Difficulty.HARD, explanation = "\"Autumn Leaves\" est une chanson française de 1945, \"Les Feuilles mortes\", composée par Joseph Kosma sur des paroles de Jacques Prévert. La version instrumentale jazz la plus célèbre est celle de Cannonball Adderley, mais le standard a été repris par de nombreux artistes comme Miles Davis ou Bill Evans."),
        Question(11868, "En quelle année \"Cookin' with the Miles Davis Quintet\" a-t-il été enregistré?", listOf("1957", "1955", "1959", "1958"), 0, "Culture", Difficulty.EXPERT, explanation = "Cookin' with the Miles Davis Quintet fait partie d'une série d'albums enregistrés lors de sessions marathon pour Prestige Records en 1956, mais l'album a été assemblé et publié en 1957."),
        Question(11869, "Quel compositeur a écrit \"All the Things You Are\"?", listOf("Jerome Kern", "Oscar Hammerstein II", "George Gershwin", "Cole Porter"), 0, "Culture", Difficulty.HARD, explanation = "Jerome Kern a composé \"All the Things You Are\" en 1939 pour la comédie musicale \"Very Warm for May\", avec des paroles d'Oscar Hammerstein II. Ce standard de jazz est l'un des morceaux les plus célèbres de Kern."),
        Question(11870, "En quelle année \"A Love Supreme\" a-t-il été enregistré?", listOf("1964", "1962", "1966", "1965"), 0, "Culture", Difficulty.HARD, explanation = "\"A Love Supreme\" est un album de jazz de John Coltrane, enregistré en une seule session le 9 décembre 1964 et sorti en 1965."),
        // CINÉMA - MARVEL ET DC (901-950)
        Question(11871, "Quel est le premier film du MCU?", listOf("Iron Man", "The Incredible Hulk", "Fantastic Four", "Blade"), 0, "Culture", Difficulty.EASY, explanation = "Iron Man, sorti en 2008, a lancé l'univers cinématographique Marvel en introduisant Tony Stark et la scène post-générique avec Nick Fury."),
        Question(11872, "En quelle année \"Iron Man\" a-t-il été publié?", listOf("2008", "2006", "2010", "2007"), 0, "Culture", Difficulty.EASY, explanation = "Le film Iron Man, qui a lancé l'univers cinématographique Marvel, est sorti en salles en 2008."),
        Question(11873, "Quel acteur a joué Iron Man dans le MCU?", listOf("Robert Downey Jr.", "Tobey Maguire", "Chris Evans", "Mark Ruffalo"), 0, "Culture", Difficulty.EASY, explanation = "Robert Downey Jr. a incarné Tony Stark / Iron Man dans le Marvel Cinematic Universe de 2008 à 2019, lançant la franchise avec le premier film Iron Man."),
        Question(11874, "Quel est le titre du premier film \"Avengers\"?", listOf("The Avengers", "Avengers: Age of Ultron", "Avengers: Infinity War", "Avengers: Endgame"), 0, "Culture", Difficulty.EASY, explanation = "Sorti en 2012, le premier film de la saga Marvel s'intitule \"The Avengers\", titre original conservé en français pour désigner l'équipe de super-héros."),
        Question(11875, "En quelle année \"The Avengers\" a-t-il été publié?", listOf("2012", "2010", "2014", "2011"), 0, "Culture", Difficulty.EASY, explanation = "The Avengers est sorti en 2012, marquant le premier crossover majeur de l'univers cinématographique Marvel, rassemblant Iron Man, Captain America, Thor et Hulk."),
        Question(11876, "Quel réalisateur a réalisé \"The Avengers\"?", listOf("Joss Whedon", "Anthony Russo", "Joe Russo", "Cate Shortland"), 0, "Culture", Difficulty.MEDIUM, explanation = "Joss Whedon a réalisé \"The Avengers\" (2012), premier film réunissant les super-héros Marvel dans une équipe commune."),
        Question(11877, "Quel film MCU introduit Spider-Man?", listOf("Captain America: Civil War", "Spider-Man: Homecoming", "The Avengers", "Ant-Man"), 0, "Culture", Difficulty.MEDIUM, explanation = "Spider-Man apparaît pour la première fois dans le MCU dans Captain America: Civil War, où Tony Stark le recrute pour combattre aux côtés des Avengers."),
        Question(11878, "En quelle année \"Captain America: Civil War\" a-t-il été publié?", listOf("2016", "2014", "2018", "2015"), 0, "Culture", Difficulty.MEDIUM, explanation = "Captain America: Civil War est sorti en 2016, marquant le treizième film de l'univers cinématographique Marvel. Il met en scène l'affrontement des Avengers suite aux accords de Sokovie."),
        Question(11879, "Quel acteur joue Captain America dans le MCU?", listOf("Chris Evans", "Chris Hemsworth", "Chris Pratt", "Chris Pine"), 0, "Culture", Difficulty.EASY, explanation = "Chris Evans a incarné Steve Rogers, alias Captain America, dans l'univers cinématographique Marvel (MCU) depuis le film Captain America: First Avenger en 2011 jusqu'à Avengers: Endgame en 2019."),
        Question(11880, "Quel est le titre du dernier film \"Avengers\" ?", listOf("Avengers: Endgame", "Avengers: Infinity War", "Avengers: Age of Ultron", "The Avengers"), 0, "Culture", Difficulty.EASY, explanation = "Avengers: Endgame est le quatrième volet de la saga Avengers, sorti en 2019, concluant l'arc narratif débuté avec Infinity War."),
        Question(11881, "En quelle année \"Avengers: Endgame\" a-t-il été publié?", listOf("2019", "2017", "2021", "2018"), 0, "Culture", Difficulty.EASY, explanation = "Avengers: Endgame est sorti en 2019, concluant la phase 3 du Marvel Cinematic Universe et devenant le film le plus rentable de l'année."),
        Question(11882, "Quel film \"Avengers\" introduit Thanos?", listOf("Avengers: Infinity War", "Avengers: Age of Ultron", "The Avengers", "Avengers: Endgame"), 0, "Culture", Difficulty.MEDIUM, explanation = "Thanos apparaît brièvement dans les scènes post-générique de \"Avengers\" et \"Avengers: L'Ère d'Ultron\", mais c'est dans \"Avengers: Infinity War\" qu'il devient le principal antagoniste et est pleinement introduit comme le titan fou cherchant les Pierres d'Infinité."),
        Question(11883, "Quel premier film DC Comics a lancé l'univers cinématique?", listOf("Man of Steel", "Batman Begins", "Wonder Woman", "Aquaman"), 0, "Culture", Difficulty.HARD, explanation = "Man of Steel, sorti en 2013, a été le premier film à lancer l'univers cinématographique DC (DC Extended Universe), suivi par Batman v Superman."),
        Question(11884, "En quelle année \"Man of Steel\" a-t-il été publié?", listOf("2013", "2011", "2015", "2012"), 0, "Culture", Difficulty.HARD, explanation = "\"Man of Steel\", le film de Zack Snyder avec Henry Cavill en Superman, est sorti en 2013. C'était le premier volet de l'univers cinématographique DC étendu."),
        Question(11885, "Quel réalisateur a réalisé \"Man of Steel\"?", listOf("Zack Snyder", "Christopher Nolan", "James Gunn", "Denis Villeneuve"), 0, "Culture", Difficulty.HARD, explanation = "Zack Snyder a réalisé \"Man of Steel\" (2013), un reboot de Superman produit par Christopher Nolan."),
        Question(11886, "Quel acteur joue Superman dans \"Man of Steel\"?", listOf("Henry Cavill", "Brandon Routh", "Tom Welling", "George Reeves"), 0, "Culture", Difficulty.MEDIUM, explanation = "Henry Cavill incarne Superman dans \"Man of Steel\" (2013), un reboot de la franchise réalisé par Zack Snyder."),
        Question(11887, "Quel est le titre du premier film \"Wonder Woman\"?", listOf("Wonder Woman", "Wonder Woman 1984", "Wonder Woman 3", "Batman v Superman"), 0, "Culture", Difficulty.HARD, explanation = "Le film de 2017, réalisé par Patty Jenkins, est simplement intitulé \"Wonder Woman\", sans numéro ni sous-titre, marquant la première apparition solo de l'héroïne au cinéma."),
        Question(11888, "En quelle année \"Wonder Woman\" a-t-il été publié?", listOf("2017", "2015", "2019", "2016"), 0, "Culture", Difficulty.HARD, explanation = "Le film Wonder Woman est sorti en 2017, réalisé par Patty Jenkins, avec Gal Gadot dans le rôle-titre."),
        Question(11889, "Quel réalisateur a réalisé \"Wonder Woman\"?", listOf("Patty Jenkins", "Zack Snyder", "James Gunn", "David Ayer"), 0, "Culture", Difficulty.HARD, explanation = "Patty Jenkins a réalisé \"Wonder Woman\" en 2017, devenant la première femme à diriger un film de super-héros majeur."),
        Question(11890, "Quelle actrice joue Wonder Woman?", listOf("Gal Gadot", "Lynda Carter", "Lucy Lawless", "Charlize Theron"), 0, "Culture", Difficulty.MEDIUM, explanation = "Gal Gadot incarne Wonder Woman dans l'univers cinématographique DC depuis le film \"Batman v Superman : L'Aube de la justice\" en 2016."),
        // MUSIQUE - EUROVISION (951-1000)
        Question(11891, "En quelle année le Concours Eurovision a-t-il débuté?", listOf("1956", "1954", "1958", "1960"), 0, "Culture", Difficulty.HARD, explanation = "Le premier Concours Eurovision de la chanson a eu lieu en 1956 à Lugano, en Suisse, avec la participation de sept pays."),
        Question(11892, "Quel pays a remporté le plus d'Eurovision?", listOf("Suède", "Norvège", "Islande", "Pays-Bas"), 0, "Culture", Difficulty.HARD, explanation = "Avec 7 victoires, la Suède est le pays le plus titré de l'histoire du concours, devant l'Irlande qui en compte 7 également mais avec moins de participations."),
        Question(11893, "Combien de fois la Suède a-t-elle remporté Eurovision?", listOf("6", "5", "7", "4"), 0, "Culture", Difficulty.HARD, explanation = "La Suède a remporté l'Eurovision à six reprises, en 1974, 1984, 1991, 1999, 2012 et 2015, ce qui en fait l'un des pays les plus titrés de l'histoire du concours."),
        Question(11894, "Quel est le titre de la chanson gagnante en 2023?", listOf("Space Man", "Mama Mia", "Tattoo", "King of the World"), 0, "Culture", Difficulty.HARD, explanation = "Space Man, interprétée par Sam Ryder, a remporté l'Eurovision 2023 pour le Royaume-Uni, obtenant le meilleur score du pays depuis 1998."),
        Question(11895, "Quel artiste a remporté Eurovision 2023?", listOf("Måneskin", "Kalush Orchestra", "Sertab Erener", "Loreen"), 1, "Culture", Difficulty.HARD, explanation = "Kalush Orchestra a remporté l'Eurovision 2023 avec leur chanson \"Stefania\", représentant l'Ukraine."),
        Question(11896, "En quelle année la France a-t-elle remporté Eurovision?", listOf("1988", "1986", "1990", "1992"), 1, "Culture", Difficulty.HARD, explanation = "La France a remporté le Concours Eurovision de la chanson en 1986 grâce à la chanson \"J'aime la vie\" interprétée par Marie Myriam."),
        Question(11897, "Quel artiste français a remporté Eurovision en 1988?", listOf("Carole Demas", "Gérard Lenorman", "Colette Boky", "Nicole"), 1, "Culture", Difficulty.EXPERT, explanation = "Gérard Lenorman a représenté la France au Concours Eurovision de la chanson en 1988 avec la chanson \"Chanteur de charme\", remportant la première place."),
        Question(11898, "Combien de fois l'Italie a-t-elle remporté Eurovision?", listOf("3", "2", "4", "5"), 0, "Culture", Difficulty.HARD, explanation = "L'Italie a remporté le Concours Eurovision de la chanson à trois reprises : en 1964 avec Gigliola Cinquetti, en 1990 avec Toto Cutugno et en 2021 avec le groupe Måneskin."),
        Question(11899, "En quelle année l'Italie a-t-elle remporté Eurovision le plus récemment?", listOf("2021", "2019", "2023", "2022"), 0, "Culture", Difficulty.HARD, explanation = "Le groupe italien Måneskin a remporté l'Eurovision 2021 à Rotterdam avec le titre \"Zitti e buoni\", offrant à l'Italie sa troisième victoire dans le concours."),
        Question(11900, "Quel artiste a remporté Eurovision 2021?", listOf("Måneskin", "Blind Channel", "Gjon's Tears", "Leroy"), 0, "Culture", Difficulty.HARD, explanation = "Le groupe italien Måneskin a remporté l'Eurovision 2021 avec la chanson \"Zitti e buoni\", marquant la troisième victoire de l'Italie dans le concours.")
